using System;using UnityEngine;using UnityEditor;using UnityEngine.UIElements;using TimelessEchoes.Quests;using TimelessEchoes.UI.Toolkit;
namespace TimelessEchoes.EditorTools {
 public static class ToolkitPinnedGoalsMigration {
 [MenuItem("Tools/UI Toolkit/Import pinned goals reference")]
 public static void Import(){if(Application.isPlaying)throw new InvalidOperationException("Main Edit mode required");const string path="Assets/UI/Toolkit/";var ui=UnityEngine.Object.FindAnyObjectByType<PinnedQuestUIManager>(FindObjectsInactive.Include);var so=new SerializedObject(ui);var row=(QuestPinUI)so.FindProperty("entryPrefab").objectReferenceValue;var root=(GameObject)so.FindProperty("rootObject").objectReferenceValue;var d=AssetDatabase.LoadAssetAtPath<ToolkitPinnedGoalsDefinition>(path+"PinnedGoals.asset");if(!d){d=ScriptableObject.CreateInstance<ToolkitPinnedGoalsDefinition>();AssetDatabase.CreateAsset(d,path+"PinnedGoals.asset");}d.expanded=(Sprite)so.FindProperty("closeSprite").objectReferenceValue;d.collapsed=(Sprite)so.FindProperty("openSprite").objectReferenceValue;d.ready=row.completedImage.sprite;d.textSize=row.progressText.fontSize;d.textColor=row.progressText.color;var face=row.progressText.font.faceInfo;d.ascentRatio=face.ascentLine/face.pointSize;d.descentRatio=-face.descentLine/face.pointSize;d.lineHeightRatio=face.lineHeight/face.pointSize;d.backgroundColor=root.transform.Find("Bg").GetComponent<UnityEngine.UI.Graphic>().color;EditorUtility.SetDirty(d);var go=new GameObject("Toolkit Pinned Goals");try{var screen=go.AddComponent<ToolkitPinnedGoals>();var native=new SerializedObject(screen);native.FindProperty("definition").objectReferenceValue=d;native.FindProperty("theme").objectReferenceValue=AssetDatabase.LoadAssetAtPath<ToolkitTheme>(path+"Theme.asset");native.FindProperty("runtimeTheme").objectReferenceValue=AssetDatabase.LoadAssetAtPath<ThemeStyleSheet>(path+"Runtime.tss");native.FindProperty("textSettings").objectReferenceValue=AssetDatabase.LoadAssetAtPath<PanelTextSettings>(path+"TextSettings.asset");native.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.SaveAsPrefabAsset(go,path+"PinnedGoals.prefab");AssetDatabase.SaveAssets();}finally{UnityEngine.Object.DestroyImmediate(go);}}
 }
}
